package com.questcape;

import com.questcape.guide.*;
import com.questcape.integration.*;
import com.questcape.progress.*;
import com.questcape.ui.GuidePanel;
import com.questcape.persistence.JsonStore;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.*;
import java.util.Map;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.*;

@Slf4j
@PluginDescriptor(name = "QuestCape", internalName = "questcape", legacyDataDirectory = "questcape",
	description = "The ordered OSRS Wiki route with local character progress", tags =
{ "quest", "questcape", "guide", "wiki" })
public class QuestCapePlugin extends Plugin implements GuidePanel.Actions
{
	@Provides
	@Singleton
	JsonStore provideJsonStore(Gson gson)
	{
		return new JsonStore(gson, this::getPluginDirectory);
	}

	@Inject
	private ClientThread clientThread;
	@Inject
	private Client client;
	@Inject
	private ClientToolbar toolbar;
	@Inject
	private GuideRepository guide;
	@Inject
	private ProgressService progress;
	@Inject
	private LiveProgressReader liveReader;
	@Inject
	private TrainingGuideResolver training;
	@Inject
	private BoundedHttp http;
	@Inject
	private BrowserLinks browser;
	@Inject
	private SpriteManager spriteManager;
	@Inject
	private SkillIconManager skillIconManager;
	private ThreadPoolExecutor worker, network;
	private GuidePanel panel;
	private NavigationButton navigation;
	private volatile boolean running;
	private final AtomicLong generation = new AtomicLong();
	private final AtomicLong liveGeneration = new AtomicLong();
	private volatile String contentStatus = "", progressStatus = "";
	private volatile boolean dirty = true, ready;
	private final AtomicBoolean livePending = new AtomicBoolean();
	private final AtomicBoolean renderQueued = new AtomicBoolean();

	private static ThreadPoolExecutor executor(String name, int threads)
	{
		return new ThreadPoolExecutor(threads, threads, 0, TimeUnit.SECONDS, new ArrayBlockingQueue<>(16), r ->
		{
			Thread t = new Thread(r, name);
			t.setDaemon(true);
			return t;
		}, new ThreadPoolExecutor.AbortPolicy());
	}

	@Override
	protected void startUp() throws Exception
	{
		running = true;
		long token = generation.incrementAndGet();
		ready = false;
		dirty = true;
		progressStatus = "";
		worker = executor("questcape-state", 1);
		network = executor("questcape-http", 2);
		work(() -> createPanel(token));
		work(() ->
		{
			try
			{
				guide.load();
				contentStatus = "Cached guide loaded.";
			}
			catch (IOException e)
			{
				contentStatus = e.getMessage();
			}
			render();
			if (guide.isStale(System.currentTimeMillis()))
			{
				refresh();
			}
		});
	}

	/** Resource decoding uses memory only and never runs on ClientThread or the EDT. */
	private void createPanel(long token)
	{
		java.awt.image.BufferedImage icon;
		try (InputStream stream = getClass().getResourceAsStream("/quest-route-icon.png"))
		{
			if (stream == null)
			{
				throw new IOException("Missing navigation icon");
			}
			try (javax.imageio.stream.ImageInputStream image =
				new javax.imageio.stream.MemoryCacheImageInputStream(stream))
			{
				java.util.Iterator<javax.imageio.ImageReader> readers = ImageIO.getImageReaders(image);
				if (!readers.hasNext())
				{
					throw new IOException("Unsupported navigation icon");
				}
				javax.imageio.ImageReader reader = readers.next();
				try
				{
					reader.setInput(image);
					icon = reader.read(0);
				}
				finally
				{
					reader.dispose();
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("QuestCape navigation icon could not be loaded ({})", e.getClass().getSimpleName());
			return;
		}
		final java.awt.image.BufferedImage loadedIcon = icon;
		Map<Skill, java.awt.image.BufferedImage> icons = new java.util.EnumMap<>(Skill.class);
		Map<Skill, java.awt.image.BufferedImage> projections = new java.util.EnumMap<>(Skill.class);
		loadSkillIcons(icons, projections);
		SwingUtilities.invokeLater(() ->
		{
			if (!valid(token))
			{
				return;
			}
			panel = new GuidePanel(this, training);
			panel.setSkillIcons(icons, projections);
			navigation = NavigationButton.builder().tooltip("QuestCape").icon(loadedIcon).priority(6).panel(panel)
				.build();
			toolbar.addNavigation(navigation);
			loadStepIcons(token);
			render();
		});
	}

	private void loadStepIcons(long token)
	{
		Map<GuideRow.Kind, Integer> sprites = Map.of(
			GuideRow.Kind.QUEST, SpriteID.AchievementDiaryIcons.BLUE_QUESTS,
			GuideRow.Kind.DIARY, SpriteID.AchievementDiaryIcons.GREEN_ACHIEVEMENT_DIARIES,
			GuideRow.Kind.TRAINING, SpriteID.SideIcons.STATS);
		sprites.forEach((kind, sprite) -> spriteManager.getSpriteAsync(sprite, 0, image ->
		{
			SwingUtilities.invokeLater(() ->
			{
				if (valid(token) && panel != null)
				{
					panel.setStepSprite(kind, image);
				}
			});
		}));
	}

	/** Prepare bundled skill images on the worker before publishing any sidebar content. */
	private void loadSkillIcons(Map<Skill, java.awt.image.BufferedImage> icons,
		Map<Skill, java.awt.image.BufferedImage> projections)
	{
		for (Skill skill : Skill.values())
		{
			java.awt.image.BufferedImage image = skillIconManager.getSkillImage(skill, false);
			if (image != null)
			{
				icons.put(skill, net.runelite.client.util.ImageUtil.resizeImage(image, 16, 16));
				projections.put(skill, net.runelite.client.util.ImageUtil.resizeImage(image, 18, 18));
			}
		}
	}

	@Override
	protected void shutDown()
	{
		running = false;
		generation.incrementAndGet();
		liveGeneration.incrementAndGet();
		guide.cancel();
		http.cancel();
		if (worker != null)
		{
			worker.shutdownNow();
		}
		if (network != null)
		{
			network.shutdownNow();
		}
		progress.logout();
		livePending.set(false);
		NavigationButton old = navigation;
		GuidePanel oldPanel = panel;
		SwingUtilities.invokeLater(() ->
		{
			if (oldPanel != null)
			{
				oldPanel.dispose();
			}
			if (old != null)
			{
				toolbar.removeNavigation(old);
			}
		});
		navigation = null;
		panel = null;
	}

	private boolean valid(long token)
	{
		return running && generation.get() == token;
	}

	private boolean work(Runnable action)
	{
		long token = generation.get();
		if (!running)
		{
			return false;
		}
		try
		{
			worker.execute(() ->
			{
				if (valid(token))
				{
					action.run();
				}
			});
			return true;
		}
		catch (RejectedExecutionException e)
		{
			show("Work queue is busy. Retry shortly.");
			return false;
		}
	}

	private void show(String value)
	{
		long token = generation.get();
		SwingUtilities.invokeLater(() ->
		{
			if (valid(token) && panel != null)
			{
				panel.message(value);
			}
		});
	}

	private void render()
	{
		if (!running || !renderQueued.compareAndSet(false, true))
		{
			return;
		}
		long token = generation.get();
		SwingUtilities.invokeLater(() ->
		{
			renderQueued.set(false);
			if (!valid(token) || panel == null)
			{
				return;
			}
			AccountProgress account = progress.current();
			String savedProgress = progress.persistenceStatus();
			String savedGuide = guide.persistenceStatus();
			panel.render(guide.current(), account,
				savedGuide == null || savedGuide.isEmpty() ? contentStatus : savedGuide,
				savedProgress == null || savedProgress.isEmpty() ? progressStatus : savedProgress, ready);
		});
	}

	@Override
	public void refresh()
	{
		if (!running)
		{
			return;
		}
		long token = generation.get();
		contentStatus = "Checking wiki…";
		render();
		try
		{
			guide.refresh(network, System.currentTimeMillis()).whenComplete((snapshot, failure) ->
			{
				if (!valid(token))
				{
					return;
				}
				contentStatus = failure == null ? "Guide is up to date." : "Refresh failed: " + cause(failure);
				render();
			});
		}
		catch (RejectedExecutionException e)
		{
			contentStatus = "Request queue is busy. Retry shortly.";
			render();
		}
	}

	@Override
	public void syncPlayer()
	{
		if (!running)
		{
			return;
		}
		long life = generation.get(), accountToken = liveGeneration.get();
		AccountProgress expected = progress.current();
		clientThread.invokeLater(() ->
		{
			if (!valid(life) || accountToken != liveGeneration.get())
			{
				return;
			}
			if (!ready || expected == null || client.getGameState() != GameState.LOGGED_IN)
			{
				show("Log in and wait for your character to be ready before syncing.");
				return;
			}
			captureProgress(true, expected.getScope());
		});
	}

	@Override
	public void manual(String scope, GuideRow row, boolean checked)
	{
		work(() ->
		{
			try
			{
				progress.toggleManual(scope, row, checked);
			}
			catch (IOException e)
			{
				show(e.getMessage());
			}
			render();
		});
	}

	@Override
	public void training(String skill)
	{
		String url = training.resolve(skill);
		long token = generation.get();
		show("Checking Theoatrix destination…");
		try
		{
			network.execute(() ->
			{
				try
				{
					String verified = training.verifyDestination(url);
					SwingUtilities.invokeLater(() ->
					{
						if (valid(token))
						{
							show(browser.open(verified));
						}
					});
				}
				catch (IOException | RuntimeException e)
				{
					if (valid(token))
					{
						show(e.getMessage() + " Link: " + url
							+ " · Click the training action to retry. Browse Theoatrix guides: "
							+ TrainingGuideResolver.FALLBACK);
					}
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			show("Request queue is busy. Retry shortly.");
		}
	}

	@Override
	public void source(String url)
	{
		if (GuideParser.safeWikiLink(url) != null || "https://creativecommons.org/licenses/by-nc-sa/3.0/".equals(url))
		{
			show(browser.open(url));
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		dirty = true;
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			ready = false;
			liveGeneration.incrementAndGet();
			progress.logout();
			progressStatus = "";
			show("");
			render();
		}
		if (state == GameState.LOGGED_IN)
		{
			ready = false;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!running || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ready = true;
		if (!dirty)
		{
			return;
		}
		captureProgress(false, null);
	}

	/** Called on ClientThread. Only the immutable observation crosses to the disk worker. */
	private void captureProgress(boolean explicit, String expectedScope)
	{
		if (!livePending.compareAndSet(false, true))
		{
			if (explicit)
			{
				show("A character sync is already running. Retry shortly.");
			}
			return;
		}
		dirty = false;
		long life = generation.get(), accountToken = liveGeneration.get(), session = progress.token();
		try
		{
			AccountProgress observation = liveReader.read();
			if (observation == null || (expectedScope != null && !expectedScope.equals(observation.getScope())))
			{
				dirty = true;
				livePending.set(false);
				if (explicit)
				{
					show("Character changed or is not ready. Wait for the next game tick and retry.");
				}
				return;
			}
			if (explicit)
			{
				progressStatus = "Syncing character…";
				render();
			}
			if (!work(() ->
			{
				try
				{
					if (!valid(life) || accountToken != liveGeneration.get())
					{
						return;
					}
					AccountProgress previous = progress.current();
					boolean newAccount = previous == null || !previous.getScope().equals(observation.getScope());
					if (!progress.acceptLive(observation, session, explicit))
					{
						return;
					}
					if (!valid(life) || accountToken != liveGeneration.get())
					{
						return;
					}
					if (newAccount)
					{
						show("");
					}
					if (explicit || newAccount)
					{
						progressStatus = "Character synced locally";
					}
					render();
				}
				catch (IOException e)
				{
					if (valid(life) && accountToken == liveGeneration.get())
					{
						dirty = true;
						progressStatus = "Could not save character progress";
						show(e.getMessage());
						render();
					}
				}
				finally
				{
					if (valid(life))
					{
						livePending.set(false);
					}
				}
			}))
			{
				dirty = true;
				livePending.set(false);
			}
		}
		catch (RuntimeException e)
		{
			dirty = true;
			livePending.set(false);
			show("Character progress is not ready yet. Retry after the next game tick.");
		}
	}

	private static String cause(Throwable failure)
	{
		while (failure.getCause() != null)
		{
			failure = failure.getCause();
		}
		return failure.getMessage();
	}
}

package com.questcape.guide;

import com.questcape.progress.Identities;
import com.questcape.progress.ActivityProgress;
import java.util.*;
import java.util.regex.*;

/** Classifies the guide's instructions independently from whether their completion can be observed. */
final class GuideClassifier
{
	private static final Pattern TRAIN = Pattern.compile(
		"(?i)\\b([a-z]++(?:\\s*(?:,|and|&)\\s*[a-z]++)*+)\\s+"
			+ "(?:from\\s+level\\s+\\d+\\s+)?(?:to\\s+(?:level\\s+)?|level\\s+to\\s+)(\\d+)");
	private static final Pattern ACTION = Pattern.compile(
		"^(?:train|start|complete|finish|do|visit|talk|speak|unlock|claim|hand|gain|reach|obtain|buy|equip|"
			+ "kill|defeat|enter|travel|collect|use|make|build|return|read|give|bring|learn|earn)\\b");
	private static final Pattern COMMENT = Pattern.compile(
		"^(?:note|tip|important|comment|reminder|recommendation)\\s*:|"
			+ "^(?:all|these|those|this|the following|from here|from this point|you can|you may|you have|"
			+ "you now|congratulations)\\b");

	private GuideClassifier()
	{
	}

	static GuideRow classify(int position, String title, String wikiTarget,
		Map<String, String> fields, Map<String, String> links, boolean fullWidth)
	{
		String normalized = Identities.normalize(title);
		String quest = Identities.quest(wikiTarget);
		if (quest == null)
		{
			quest = Identities.quest(title.replaceAll("(?i)\\(miniquest\\)", "").trim());
		}
		Map<String, Integer> targets = new LinkedHashMap<>();
		GuideRow.Kind kind;
		if (normalized.startsWith("note:") || fullWidth && isComment(normalized, quest == null))
		{
			kind = GuideRow.Kind.INFORMATION;
			quest = null;
		}
		else if (normalized.startsWith("train "))
		{
			kind = GuideRow.Kind.TRAINING;
			readTargets(title, targets);
			quest = null;
		}
		else if (normalized.contains("(miniquest)") || normalized.startsWith("start miniquest:"))
		{
			kind = GuideRow.Kind.MINIQUEST;
		}
		else if (ActivityProgress.diary(title) != null
			|| normalized.contains("diary") && !normalized.startsWith("hand in"))
		{
			kind = GuideRow.Kind.DIARY;
			quest = null;
		}
		else if (normalized.startsWith("hand in") || normalized.startsWith("claim "))
		{
			kind = GuideRow.Kind.ACTIVITY;
			quest = null;
		}
		else if (normalized.startsWith("unlock:") || normalized.startsWith("unlock "))
		{
			kind = GuideRow.Kind.UNLOCK;
			quest = null;
		}
		else if (quest != null)
		{
			kind = GuideRow.Kind.QUEST;
		}
		else
		{
			kind = GuideRow.Kind.UNKNOWN;
		}
		String stage = normalized.startsWith("start ") ? ":start" : ":finish";
		String key = kind.name() + ":" + (quest == null
			? GuideParser.digest(Identities.normalize(wikiTarget) + "|" + normalized) : quest + stage);
		return new GuideRow(key, position, kind, title, wikiTarget, quest, targets, fields, links);
	}

	private static boolean isComment(String title, boolean noQuestIdentity)
	{
		return !ACTION.matcher(title).find()
			&& (COMMENT.matcher(title).find() || noQuestIdentity && (title.endsWith(".") || title.endsWith("!")));
	}

	private static void readTargets(String title, Map<String, Integer> targets)
	{
		// Parenthetical recommendations are not requirements for completing the training step.
		Matcher match = TRAIN.matcher(title.replaceAll("\\([^)]*\\)", ""));
		while (match.find())
		{
			int target;
			try
			{
				target = Integer.parseInt(match.group(2));
			}
			catch (NumberFormatException e)
			{
				targets.clear();
				return;
			}
			for (String name : match.group(1).split("(?i)\\s*(?:,|and|&)\\s*"))
			{
				String skill = Identities.normalize(name).equals("combat") ? "COMBAT" : Identities.skill(name);
				if (skill == null || target < 1 || target > 126)
				{
					targets.clear();
					return;
				}
				targets.put(skill, target);
			}
		}
	}
}

package com.questcape.guide;

import com.questcape.progress.Identities;
import com.questcape.progress.ActivityProgress;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import javax.inject.Inject;

public class GuideParser
{
	private static final String CAPTION = "old school runescape quest guide";
	private static final List<String> HEADERS = Arrays.asList("Quest/Activity", "Quick Guide", "New levels after quest",
		"Quest points", "Total QP", "Additional info", "Location");

	@Inject
	public GuideParser()
	{
	}

	public List<GuideRow> parse(String html) throws IOException
	{
		if (html == null || html.length() > 4_000_000)
		{
			throw new IOException("Guide response exceeds limits");
		}
		HtmlTree.Node document = HtmlTree.parse(html);
		List<HtmlTree.Node> candidates = new ArrayList<>();
		for (HtmlTree.Node table : document.all("table"))
		{
			if (table.children("caption").stream().anyMatch(c -> Identities.normalize(c.text()).equals(CAPTION)))
			{
				candidates.add(table);
			}
		}
		if (candidates.size() != 1)
		{
			throw new IOException("Expected one captioned guide table; found " + candidates.size());
		}
		List<HtmlTree.Node> physical = candidates.get(0).all("tr");
		if (physical.size() < 2 || physical.size() > 2000)
		{
			throw new IOException("Guide table is empty or oversized");
		}
		Map<Integer, Span> spans = new HashMap<>();
		List<GuideRow> rows = new ArrayList<>();
		List<String> headers = null;
		for (HtmlTree.Node tr : physical)
		{
			List<HtmlTree.Node> cells = new ArrayList<>();
			for (Object child : tr.content)
			{
				if (child instanceof HtmlTree.Node)
				{
					HtmlTree.Node node = (HtmlTree.Node)child;
					if (node.tag.equals("td") || node.tag.equals("th"))
					{
						cells.add(node);
					}
				}
			}
			if (cells.isEmpty())
			{
				continue;
			}
			HtmlTree.Node[] grid = new HtmlTree.Node[7];
			for (Iterator<Map.Entry<Integer, Span>> it = spans.entrySet().iterator(); it.hasNext();)
			{
				Map.Entry<Integer, Span> entry = it.next();
				grid[entry.getKey()] = entry.getValue().node;
				if (--entry.getValue().remaining == 0)
				{
					it.remove();
				}
			}
			int column = 0;
			for (HtmlTree.Node cell : cells)
			{
				while (column < 7 && grid[column] != null)
				{
					column++;
				}
				int colspan = span(cell, "colspan"), rowspan = span(cell, "rowspan");
				if (column + colspan > 7)
				{
					throw new IOException("Unexpected guide column count");
				}
				for (int j = 0; j < colspan; j++)
				{
					if (grid[column] != null)
					{
						throw new IOException("Overlapping merged cells");
					}
					grid[column] = cell;
					if (rowspan > 1)
					{
						spans.put(column, new Span(cell, rowspan - 1));
					}
					column++;
				}
			}
			if (Arrays.stream(grid).anyMatch(Objects::isNull))
			{
				throw new IOException("Incomplete guide row");
			}
			if (headers == null)
			{
				headers = new ArrayList<>();
				for (HtmlTree.Node cell : grid)
				{
					headers.add(cell.text());
				}
				for (String header : HEADERS)
				{
					if (headers.stream().noneMatch(h -> Identities.normalize(h).equals(Identities.normalize(header))))
					{
						throw new IOException("Guide headers changed: " + headers);
					}
				}
				continue;
			}
			Map<String, String> fields = new LinkedHashMap<>(), links = new LinkedHashMap<>();
			for (int j = 0; j < 7; j++)
			{
				fields.put(headers.get(j), grid[j].text());
			}
			for (HtmlTree.Node anchor : tr.all("a"))
			{
				String href = safeWikiLink(anchor.attr("href"));
				if (href != null && !anchor.text().isEmpty())
				{
					links.put(href, anchor.text());
				}
			}
			HtmlTree.Node titleCell = grid[headers.indexOf(
				headers.stream().filter(h -> Identities.normalize(h).equals("quest/activity")).findFirst().get())];
			String title = titleCell.text();
			if (title.isBlank())
			{
				throw new IOException("Empty guide action");
			}
			String wikiTarget = "";
			for (HtmlTree.Node a : titleCell.all("a"))
			{
				String href = safeWikiLink(a.attr("href"));
				if (href != null && !a.text().isBlank())
				{
					wikiTarget = wikiTitle(href);
					break;
				}
			}
			boolean fullWidth = Arrays.stream(grid).allMatch(cell -> cell == titleCell);
			rows.add(classify(rows.size(), title, wikiTarget, fields, links, fullWidth));
		}
		if (!spans.isEmpty() || rows.isEmpty())
		{
			throw new IOException("Truncated guide table");
		}
		return distinguishRepeatedRows(rows);
	}

	/** Upgrade cached classifications offline; the stored field layout identifies full-width rows. */
	public GuideSnapshot reclassify(GuideSnapshot snapshot)
	{
		List<GuideRow> rows = new ArrayList<>();
		for (GuideRow row : snapshot.getRows())
		{
			boolean fullWidth = row.getFields().values().stream().allMatch(row.getTitle()::equals);
			rows.add(classify(row.getPosition(), row.getTitle(), row.getWikiTarget(),
				row.getFields(), row.getLinks(), fullWidth));
		}
		return new GuideSnapshot(snapshot.getRevision(), snapshot.getRetrievedAt(), snapshot.getValidatedAt(),
			snapshot.getEtag(), snapshot.getLastModified(), distinguishRepeatedRows(rows));
	}

	/** Repair older truncated balloon titles only when retained validated links identify one destination. */
	private static GuideRow classify(int position, String title, String wikiTarget,
		Map<String, String> fields, Map<String, String> links, boolean fullWidth)
	{
		if (Identities.normalize(title).equals("unlock: balloon transport system to"))
		{
			Set<String> destinations = new LinkedHashSet<>();
			for (String url : links.keySet())
			{
				String safe = safeWikiLink(url);
				if (safe != null)
				{
					String candidate = "Unlock: Balloon transport system to " + wikiTitle(safe);
					if (ActivityProgress.unlock(candidate) != null)
					{
						destinations.add(candidate);
					}
				}
			}
			if (destinations.size() == 1)
			{
				String oldTitle = title;
				title = destinations.iterator().next();
				Map<String, String> repaired = new LinkedHashMap<>(fields);
				String repairedTitle = title;
				repaired.replaceAll((key, value) -> value.equals(oldTitle) ? repairedTitle : value);
				fields = repaired;
			}
		}
		return GuideClassifier.classify(position, title, wikiTarget, fields, links, fullWidth);
	}

	private static List<GuideRow> distinguishRepeatedRows(List<GuideRow> rows)
	{
		// Keep even identical repetitions visible, but never share a manual check between indistinguishable actions.
		Map<String, Long> counts = rows.stream()
			.collect(java.util.stream.Collectors.groupingBy(GuideRow::getKey, java.util.stream.Collectors.counting()));
		Map<String, Integer> occurrences = new HashMap<>();
		for (int i = 0; i < rows.size(); i++)
		{
			GuideRow row = rows.get(i);
			if (counts.get(row.getKey()) > 1)
			{
				String key = row.getKey() + ":repeated:" + occurrences.merge(row.getKey(), 1, Integer::sum);
				rows.set(i, new GuideRow(key, i, row.getKind(), row.getTitle(), row.getWikiTarget(),
					row.getQuestIdentity(), row.getTargets(), row.getFields(), row.getLinks()));
			}
		}
		return rows;
	}

	private static int span(HtmlTree.Node node, String name) throws IOException
	{
		if (node.attr(name).isEmpty())
		{
			return 1;
		}
		try
		{
			int value = Integer.parseInt(node.attr(name));
			if (value < 1 || value > 100)
			{
				throw new NumberFormatException();
			}
			return value;
		}
		catch (NumberFormatException e)
		{
			throw new IOException("Invalid merged cell", e);
		}
	}

	private static final class Span
	{
		final HtmlTree.Node node;
		int remaining;

		Span(HtmlTree.Node node, int remaining)
		{
			this.node = node;
			this.remaining = remaining;
		}
	}

	public static String safeWikiLink(String href)
	{
		try
		{
			URI uri = URI.create(GuideSnapshot.SOURCE).resolve(href);
			if (!"https".equalsIgnoreCase(uri.getScheme())
				|| !"oldschool.runescape.wiki".equalsIgnoreCase(uri.getHost())
				|| uri.getUserInfo() != null || (uri.getPort() != -1 && uri.getPort() != 443))
			{
				return null;
			}
			return uri.toASCIIString();
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static String wikiTitle(String validatedUrl)
	{
		return URI.create(validatedUrl).getPath().replaceFirst("^/w/", "").replace('_', ' ');
	}

	public static String digest(String value)
	{
		try
		{
			byte[] bytes = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder out = new StringBuilder();
			for (byte b : bytes)
			{
				out.append(String.format("%02x", b));
			}
			return out.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package com.questcape.guide;

import com.google.gson.*;
import com.questcape.integration.BoundedHttp;
import com.questcape.persistence.JsonStore;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;

@Singleton
@Slf4j
public class GuideRepository
{
	public static final String ENDPOINT = "https://oldschool.runescape.wiki/api.php?action=parse&page=Optimal_quest_guide&prop=text%7Crevid&format=json";
	public static final long MAX_AGE = TimeUnit.HOURS.toMillis(24);
	private final GuideParser parser;
	private final BoundedHttp http;
	private final JsonStore store;
	private volatile GuideSnapshot snapshot;
	private long nextRefresh;
	private CompletableFuture<GuideSnapshot> pending;
	private long generation;
	private final Object persistenceLock = new Object();
	private volatile String persistenceStatus = "";
	private boolean unreadable;

	@Inject
	public GuideRepository(GuideParser parser, BoundedHttp http, JsonStore store)
	{
		this.parser = parser;
		this.http = http;
		this.store = store;
	}

	public GuideSnapshot load() throws IOException
	{
		long token;
		synchronized (this)
		{
			token = generation;
		}
		synchronized (persistenceLock)
		{
			GuideSnapshot saved;
			try
			{
				saved = store.read("guide", "standard", GuideSnapshot.class);
				if (saved != null)
				{
					validate(saved, null);
				}
				unreadable = false;
			}
			catch (IOException e)
			{
				unreadable = true;
				throw e;
			}
			if (saved != null)
			{
				saved = parser.reclassify(saved);
				synchronized (this)
				{
					if (token == generation)
					{
						snapshot = saved;
					}
				}
			}
		}
		return snapshot;
	}

	public GuideSnapshot current()
	{
		return snapshot;
	}

	public String persistenceStatus()
	{
		return persistenceStatus;
	}

	public boolean isStale(long now)
	{
		return snapshot == null || now - snapshot.getValidatedAt() >= MAX_AGE;
	}

	public synchronized CompletableFuture<GuideSnapshot> refresh(Executor executor, long now)
	{
		if (pending != null && !pending.isDone())
		{
			return pending;
		}
		if (now < nextRefresh)
		{
			return CompletableFuture.failedFuture(new IOException("Guide refresh cooldown; retry shortly"));
		}
		nextRefresh = now + 5000;
		long token = generation;
		pending = CompletableFuture.supplyAsync(() ->
		{
			try
			{
				GuideSnapshot previous = snapshot;
				Map<String, String> headers = new HashMap<>();
				if (previous != null)
				{
					if (previous.getEtag() != null)
					{
						headers.put("If-None-Match", previous.getEtag());
					}
					if (previous.getLastModified() != null)
					{
						headers.put("If-Modified-Since", previous.getLastModified());
					}
				}
				BoundedHttp.Result response = http.get(ENDPOINT, headers, 4_000_000);
				GuideSnapshot candidate;
				long received = System.currentTimeMillis();
				if (response.getCode() == 304 && previous != null)
				{
					candidate = previous.revalidated(received);
				}
				else
				{
					if (response.getCode() != 200)
					{
						throw new IOException("Wiki returned HTTP " + response.getCode());
					}
					JsonObject parse = new JsonParser().parse(response.getBody()).getAsJsonObject()
						.getAsJsonObject("parse");
					if (parse == null || !parse.has("text"))
					{
						throw new IOException("Wiki parse response is missing content");
					}
					String html = parse.getAsJsonObject("text").get("*").getAsString();
					String revision = parse.has("revid") ? parse.get("revid").getAsString() : null;
					// The JDK parser repairs HTML, so independently require complete source table termination.
					if (!html.toLowerCase(Locale.ROOT).contains("</table>"))
					{
						throw new IOException("Unterminated guide table");
					}
					candidate = new GuideSnapshot(revision, received, received, response.getEtag(),
						response.getLastModified(), parser.parse(html));
					validate(candidate, previous);
				}
				synchronized (persistenceLock)
				{
					synchronized (this)
					{
						checkActive(token);
					}
					String savedStatus = "";
					try
					{
						if (unreadable)
						{
							GuideSnapshot retained = store.read("guide", "standard", GuideSnapshot.class);
							if (retained != null)
							{
								validate(retained, null);
							}
							unreadable = false;
						}
						store.write("guide", "standard", candidate);
					}
					catch (IOException e)
					{
						savedStatus = "Route unsaved; cache unavailable. Refresh to retry.";
						log.debug("QuestCape guide cache write failed ({})", e.getClass().getSimpleName());
					}
					synchronized (this)
					{
						checkActive(token);
						snapshot = candidate;
						persistenceStatus = savedStatus;
					}
				}
				return candidate;
			}
			catch (IOException | RuntimeException e)
			{
				throw new CompletionException(e);
			}
		}, executor);
		return pending;
	}

	private void checkActive(long token) throws InterruptedIOException
	{
		if (token != generation || Thread.currentThread().isInterrupted())
		{
			throw new InterruptedIOException("Refresh canceled");
		}
	}

	public synchronized void cancel()
	{
		generation++;
		if (pending != null)
		{
			pending.cancel(true);
		}
	}

	public static void validate(GuideSnapshot candidate, GuideSnapshot previous) throws IOException
	{
		if (candidate.getSchema() != GuideSnapshot.SCHEMA || !GuideSnapshot.SOURCE.equals(candidate.getSource())
			|| candidate.getRows() == null || candidate.getRows().isEmpty() || candidate.getRows().size() > 2000
			|| candidate.getRetrievedAt() <= 0 || candidate.getValidatedAt() <= 0)
		{
			throw new IOException("Invalid guide cache");
		}
		for (GuideRow row : candidate.getRows())
		{
			if (row == null || row.getKey() == null || row.getTitle() == null || row.getTitle().isBlank()
				|| row.getKind() == null || row.getFields() == null || row.getFields().size() != 7
				|| row.getTargets() == null
				|| row.getLinks() == null)
			{
				throw new IOException("Invalid guide row");
			}
		}
		if (previous != null && candidate.getRows().size() < previous.getRows().size() * 0.8)
		{
			throw new IOException("Suspicious guide truncation; keeping the last valid revision");
		}
	}
}

package com.questcape.guide;

import java.util.*;
import lombok.Value;
import com.questcape.progress.ActivityProgress;

@Value
public class GuideRow
{
	public enum Kind
	{
		QUEST, MINIQUEST, TRAINING, DIARY, UNLOCK, ACTIVITY, UNKNOWN, INFORMATION
	}

	String key;
	int position;
	Kind kind;
	String title;
	String wikiTarget;
	String questIdentity;
	String activityIdentity;
	Map<String, Integer> targets;
	Map<String, String> fields;
	Map<String, String> links;

	public GuideRow(String key, int position, Kind kind, String title, String wikiTarget,
		String questIdentity, Map<String, Integer> targets, Map<String, String> fields, Map<String, String> links)
	{
		this.key = key;
		this.position = position;
		this.kind = kind;
		this.title = title;
		this.wikiTarget = wikiTarget;
		this.questIdentity = questIdentity;
		this.activityIdentity = kind == Kind.DIARY ? ActivityProgress.diary(title)
			: kind == Kind.UNLOCK ? ActivityProgress.unlock(title)
			: kind == Kind.ACTIVITY ? ActivityProgress.handIn(title) : null;
		this.targets = Collections.unmodifiableMap(new LinkedHashMap<>(targets));
		this.fields = Collections.unmodifiableMap(new LinkedHashMap<>(fields));
		this.links = Collections.unmodifiableMap(new LinkedHashMap<>(links));
	}

	public boolean isManual()
	{
		return !key.contains(":repeated:") && kind == Kind.UNLOCK && ActivityProgress.isKudos(title);
	}

	public boolean isActionable()
	{
		return kind != Kind.INFORMATION;
	}
}

