		}
	}
}

package com.questcape.integration;

import com.questcape.progress.Identities;
import java.io.*;
import java.net.URI;
import java.util.*;
import javax.inject.*;

@Singleton
public class TrainingGuideResolver
{
	public static final String FALLBACK = "https://www.theoatrix.net/all-guides";
	private final Properties urls = new Properties();
	private final BoundedHttp http;

	@Inject
	public TrainingGuideResolver(BoundedHttp http)
	{
		this.http = http;
		try (InputStream in = TrainingGuideResolver.class.getResourceAsStream("/theoatrix.properties"))
		{
			if (in == null)
			{
				throw new IllegalStateException("Missing packaged training links");
			}
			urls.load(in);
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Cannot read training links", e);
		}
	}

	public String resolve(String skill)
	{
		String id = Identities.skill(skill);
		String candidate = urls.getProperty(id == null ? "" : id, FALLBACK);
		return safe(candidate) ? candidate : FALLBACK;
	}

	public String label(String skill)
	{
		return resolve(skill).equals(FALLBACK) ? "Browse Theoatrix guides"
			: skill.replace('_', ' ') + " · Theoatrix guide";
	}

	public static boolean safe(String value)
	{
		try
		{
			URI uri = URI.create(value);
			return "https".equalsIgnoreCase(uri.getScheme()) && ("theoatrix.net".equalsIgnoreCase(uri.getHost())
				|| "www.theoatrix.net".equalsIgnoreCase(uri.getHost())) && uri.getUserInfo() == null
				&& (uri.getPort() == -1 || uri.getPort() == 443);
		}
		catch (IllegalArgumentException e)
		{
			return false;
		}
	}

	/** Validate every redirect before browser navigation. Runs only after user activation, off the EDT. */
	public String verifyDestination(String url) throws IOException
	{
		for (int redirects = 0; redirects < 5; redirects++)
		{
			if (!safe(url))
			{
				throw new IOException("Unsafe training destination. Use Browse Theoatrix guides.");
			}
			BoundedHttp.Result response = http.get(url, Collections.emptyMap(), 4_000_000);
			if (response.getCode() == 200)
			{
				return url;
			}
			if (response.getCode() < 300 || response.getCode() > 399 || response.getLocation() == null)
			{
				throw new IOException(
					"Theoatrix returned HTTP " + response.getCode() + ". Retry or copy the guide link.");
			}
			try
			{
				url = URI.create(url).resolve(response.getLocation()).toString();
			}
			catch (IllegalArgumentException e)
			{
				throw new IOException("Invalid training redirect", e);
			}
		}
		throw new IOException("Too many training-guide redirects.");
	}
}

package com.questcape.persistence;

import com.google.gson.*;
import com.questcape.guide.GuideParser;
import java.io.*;
import java.nio.file.StandardCopyOption;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

@Slf4j
public class JsonStore
{
	public interface Directory
	{
		Filepath get() throws IOException;
	}

	private final Gson gson;
	private final Directory directory;
	private Filepath root;

	public JsonStore(Gson gson, Directory directory)
	{
		this.gson = gson;
		this.directory = directory;
	}

	private Filepath path(String category, String key) throws IOException
	{
		if (!"guide".equals(category) && !"progress".equals(category))
		{
			throw new IOException("Unsupported cache category");
		}
		if (root == null)
		{
			root = directory.get();
		}
		return root.joinSegment(category).joinSegment(GuideParser.digest(key) + ".json");
	}

	public synchronized <T> T read(String category, String key, Class<T> type) throws IOException
	{
		try
		{
			Filepath file = path(category, key);
			if (!file.exists())
			{
				return null;
			}
			if (file.size() > 4_000_000)
			{
				throw new IOException("Saved data exceeds size limit");
			}
			try (Reader reader = file.openBufferedReader())
			{
				StringBuilder content = new StringBuilder();
				char[] buffer = new char[8192];
				int read;
				while ((read = reader.read(buffer)) != -1)
				{
					if (content.length() + read > 4_000_000)
					{
						throw new IOException("Saved data exceeds size limit");
					}
					content.append(buffer, 0, read);
				}
				JsonObject object = new JsonParser().parse(content.toString()).getAsJsonObject();
				if (!object.has("schema") || object.get("schema").getAsInt() != 1)
				{
					throw new IOException("Unknown saved-data schema; original file retained");
				}
				return gson.fromJson(object, type);
			}
		}
		catch (RuntimeException e)
		{
			throw new IOException("Saved data could not be read; original file retained", e);
		}
	}

	public synchronized void write(String category, String key, Object value) throws IOException
	{
		Filepath temp = null;
		try
		{
			Filepath destination = path(category, key);
			destination.getParent().createDirectories();
			temp = destination.getParent().createTempFile("candidate-", ".tmp");
			temp.write(gson.toJson(value));
			// Refuse an unsafe/non-atomic replacement; the previous good file stays intact.
			temp.moveTo(destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (RuntimeException e)
		{
			throw new IOException("Saved data could not be written; original file retained", e);
		}
		finally
		{
			if (temp != null)
			{
				try
				{
					temp.deleteIfExists();
				}
				catch (IOException | RuntimeException e)
				{
					log.debug("QuestCape temporary cache cleanup failed ({})", e.getClass().getSimpleName());
				}
			}
		}
	}
}

package com.questcape.progress;

import java.util.*;
import lombok.Value;

@Value
public class AccountProgress
{
	public enum QuestStatus
	{
		INCOMPLETE, IN_PROGRESS, COMPLETE
	}

	int schema = 1;
	String scope;
	String username;
	String mode;
	String source;
	long retrievedAt;
	Long observedAt;
	Map<String, QuestStatus> quests;
	Map<String, Integer> levels;
	Map<String, Boolean> activities;
	Set<String> manual;

	public AccountProgress(String scope, String username, String mode, String source, long retrievedAt,
		Long observedAt, Map<String, QuestStatus> quests, Map<String, Integer> levels,
		Map<String, Boolean> activities, Set<String> manual)
	{
		this.scope = scope;
		this.username = username;
		this.mode = mode;
		this.source = source;
		this.retrievedAt = retrievedAt;
		this.observedAt = observedAt;
		this.quests = Collections.unmodifiableMap(new HashMap<>(quests));
		this.levels = Collections.unmodifiableMap(new HashMap<>(levels));
		this.activities = Collections.unmodifiableMap(new HashMap<>(activities));
		this.manual = Collections.unmodifiableSet(new HashSet<>(manual));
	}

	public AccountProgress withManual(Set<String> checks)
	{
		return new AccountProgress(scope, username, mode, source, retrievedAt, observedAt, quests, levels, activities,
			checks);
	}
}

