		add("WILDERNESS_HARD", VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_HARD_REWARD);
		add("WILDERNESS_ELITE", VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE, VarbitID.WILDERNESS_ELITE_REWARD);
	}

	private ActivityProgress()
	{
	}

	private static void add(String identity, int complete, int reward)
	{
		add(identity, complete, reward, 1);
	}

	private static void add(String identity, int complete, int reward, int completedValue)
	{
		DIARIES.put(identity, new int[] {complete, reward, completedValue});
	}

	/** Only whole-tier instructions are mapped; individual tasks must not inherit tier completion. */
	public static String diary(String title)
	{
		String text = Identities.normalize(title);
		if (!text.contains("diary") || text.matches(".*\\btasks?\\b.*"))
		{
			return null;
		}
		String match = null;
		for (String identity : DIARIES.keySet())
		{
			String[] parts = identity.toLowerCase(Locale.ROOT).split("_");
			if (text.matches(".*\\b" + parts[0] + "\\b.*") && text.matches(".*\\b" + parts[1] + "\\b.*"))
			{
				if (match != null)
				{
					return null;
				}
				match = "DIARY:" + identity;
			}
		}
		boolean reward = text.startsWith("claim ") || text.startsWith("collect ") || text.startsWith("receive ");
		return match == null ? null : match + (reward ? ":reward" : ":complete");
	}

	public static Map<String, Boolean> readDiaries(Client client)
	{
		Map<String, Boolean> facts = new HashMap<>();
		DIARIES.forEach((identity, vars) ->
		{
			facts.put("DIARY:" + identity + ":complete", client.getVarbitValue(vars[0]) == vars[2]);
			facts.put("DIARY:" + identity + ":reward", client.getVarbitValue(vars[1]) == 1);
		});
		return facts;
	}

	public static String unlock(String title)
	{
		String text = Identities.normalize(title);
		String prefix = "unlock: balloon transport system to ";
		if (text.startsWith(prefix) && BALLOONS.containsKey(text.substring(prefix.length())))
		{
			return balloonIdentity(text.substring(prefix.length()));
		}
		if (text.equals("unlock: stronghold of security"))
		{
			return "UNLOCK:STRONGHOLD_COINS";
		}
		if (text.equals("unlock: museum camp"))
		{
			return "UNLOCK:MUSEUM_CAMP_REWARD";
		}
		return null;
	}

	public static String handIn(String title)
	{
		String text = Identities.normalize(title);
		return text.startsWith("hand in the diary of herbi flax to the apothecary")
			? "HAND_IN:HERBI_FLAX" : null;
	}

	public static boolean isKudos(String title)
	{
		String text = Identities.normalize(title);
		return text.equals("unlock: varrock museum kudos") || text.equals("unlock: more varrock museum kudos");
	}

	private static String balloonIdentity(String destination)
	{
		return "UNLOCK:BALLOON:" + destination.toUpperCase(Locale.ROOT).replace(' ', '_');
	}

	public static Map<String, Boolean> readActivities(Client client)
	{
		Map<String, Boolean> facts = readDiaries(client);
		BALLOONS.forEach((destination, varbit) ->
			facts.put(balloonIdentity(destination), client.getVarbitValue(varbit) == 1));
		// This guide asks for the 10,000 coins on floors 1–3, not the fourth-floor boots.
		facts.put("UNLOCK:STRONGHOLD_COINS", client.getVarbitValue(VarbitID.SOS_EMOTE_FLAP) == 1
			&& client.getVarbitValue(VarbitID.SOS_EMOTE_DOH) == 1
			&& client.getVarbitValue(VarbitID.SOS_EMOTE_IDEA) == 1);
		// Peter's camp reward is distinct from access, individual improvements, and other island tasks.
		facts.put("UNLOCK:MUSEUM_CAMP_REWARD", client.getVarbitValue(VarbitID.FOSSIL_TASKREWARDS_CAMP) == 1);
		facts.put("HAND_IN:HERBI_FLAX", (client.getVarpValue(VarPlayerID.MORTTONMULTI)
			& (1 << HERBI_FLAX_HANDED_IN_BIT)) != 0);
		return facts;
	}

	public static void readMiniquests(Client client, Map<String, AccountProgress.QuestStatus> quests)
	{
		quests.put("NATURAL_HISTORY_QUIZ", client.getVarbitValue(VarbitID.VM_NATHIS_REWARD_GIVEN) == 1
			? AccountProgress.QuestStatus.COMPLETE
			: client.getVarbitValue(VarbitID.VM_NATHIS_AGREED) == 1
				? AccountProgress.QuestStatus.IN_PROGRESS : AccountProgress.QuestStatus.INCOMPLETE);
		int waves = client.getVarbitValue(VarbitID.KR_KNIGHTWAVES_STATE);
		quests.put("KNIGHT_WAVES_TRAINING_GROUNDS", waves >= 8 ? AccountProgress.QuestStatus.COMPLETE
			: waves > 0 ? AccountProgress.QuestStatus.IN_PROGRESS : AccountProgress.QuestStatus.INCOMPLETE);
	}
}

package com.questcape.progress;

import com.questcape.guide.GuideRow;
import lombok.Value;
import net.runelite.api.Experience;

@Value
public class Completion
{
	public enum State
	{
		COMPLETE, INCOMPLETE, IN_PROGRESS, UNKNOWN, INFORMATION
	}

	State state;
	boolean manual;

	public String label()
	{
		String label;
		switch (state)
		{
		case COMPLETE:
			label = "✓ Complete";
			break;
		case IN_PROGRESS:
			label = "◐ In progress";
			break;
		case INCOMPLETE:
			label = "○ Incomplete";
			break;
		case INFORMATION:
			label = "Information";
			break;
		default:
			label = manual ? "○ Not checked" : "? Unknown";
		}
		return label + (manual ? " · manual" : "");
	}

	public static Completion of(GuideRow row, AccountProgress progress)
	{
		if (!row.isActionable())
		{
			return new Completion(State.INFORMATION, false);
		}
		if (progress == null)
		{
			return new Completion(State.UNKNOWN, false);
		}
		if (row.getQuestIdentity() != null)
		{
			AccountProgress.QuestStatus state = progress.getQuests().get(row.getQuestIdentity());
			if (row.getKey().contains(":start") && state == AccountProgress.QuestStatus.IN_PROGRESS)
			{
				return new Completion(State.COMPLETE, false);
			}
			return new Completion(state == null ? State.UNKNOWN : State.valueOf(state.name()), false);
		}
		if (row.getKind() == GuideRow.Kind.TRAINING)
		{
			boolean missing = row.getTargets().isEmpty();
			for (java.util.Map.Entry<String, Integer> target : row.getTargets().entrySet())
			{
				Integer level = level(progress, target.getKey());
				if (level == null)
				{
					missing = true;
				}
				else if (level < target.getValue())
				{
					return new Completion(State.INCOMPLETE, false);
				}
			}
			return new Completion(missing ? State.UNKNOWN : State.COMPLETE, false);
		}
		if (row.getKind() == GuideRow.Kind.DIARY && row.getActivityIdentity() == null
			|| row.getKind() == GuideRow.Kind.MINIQUEST)
		{
			return new Completion(State.UNKNOWN, false);
		}
		Boolean fact = progress.getActivities().get(row.getActivityIdentity() == null
			? row.getKey() : row.getActivityIdentity());
		if (fact != null)
		{
			return new Completion(fact ? State.COMPLETE : State.INCOMPLETE, false);
		}
		if (row.isManual())
		{
			return new Completion(progress.getManual().contains(row.getKey()) ? State.COMPLETE : State.UNKNOWN, true);
		}
		return new Completion(State.UNKNOWN, false);
	}

	private static Integer level(AccountProgress progress, String skill)
	{
		java.util.Map<String, Integer> levels = progress.getLevels();
		if (!"COMBAT".equals(skill))
		{
			return levels.get(skill);
		}
		String[] combatSkills = {"ATTACK", "STRENGTH", "DEFENCE", "HITPOINTS", "MAGIC", "RANGED", "PRAYER"};
		for (String combatSkill : combatSkills)
		{
			Integer level = levels.get(combatSkill);
			if (level == null || level <= 0)
			{
				return null;
			}
		}
		return Experience.getCombatLevel(levels.get("ATTACK"), levels.get("STRENGTH"), levels.get("DEFENCE"),
			levels.get("HITPOINTS"), levels.get("MAGIC"), levels.get("RANGED"), levels.get("PRAYER"));
	}
}

package com.questcape.progress;

import java.text.Normalizer;
import java.util.*;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

public final class Identities
{
	private static final Map<String, String> QUESTS = new HashMap<>();
	static
	{
		for (Quest quest : Quest.values())
		{
			QUESTS.put(normalize(quest.getName()), quest.name());
		}
		QUESTS.put("natural history quiz", "NATURAL_HISTORY_QUIZ");
		QUESTS.put("knight waves training grounds", "KNIGHT_WAVES_TRAINING_GROUNDS");
		alias("Recipe for Disaster/Freeing the Mountain Dwarf", "Recipe for Disaster - Mountain Dwarf");
		alias("Recipe for Disaster/Freeing the Goblin generals", "Recipe for Disaster - Wartface & Bentnoze");
		alias("Recipe for Disaster/Freeing Pirate Pete", "Recipe for Disaster - Pirate Pete");
		alias("Recipe for Disaster/Freeing the Lumbridge Guide", "Recipe for Disaster - Lumbridge Guide");
		alias("Recipe for Disaster/Freeing Evil Dave", "Recipe for Disaster - Evil Dave");
		alias("Recipe for Disaster/Freeing Skrach Uglogwee", "Recipe for Disaster - Skrach Uglogwee");
		alias("Recipe for Disaster/Freeing Sir Amik Varze", "Recipe for Disaster - Sir Amik Varze");
		alias("Recipe for Disaster/Freeing King Awowogei", "Recipe for Disaster - King Awowogei");
		alias("Recipe for Disaster/Another Cook's Quest", "Recipe for Disaster - Another Cook's Quest");
		alias("Recipe for Disaster/Defeating the Culinaromancer", "Recipe for Disaster - Culinaromancer");
	}

	private Identities()
	{
	}

	private static void alias(String source, String target)
	{
		String id = QUESTS.get(normalize(target));
		if (id != null)
		{
			QUESTS.put(normalize(source), id);
		}
	}

	public static String normalize(String text)
	{
		return Normalizer.normalize(text == null ? "" : text, Normalizer.Form.NFKC)
			.replace('_', ' ').replace('\u00a0', ' ').replace('\u2019', '\'')
			.replace('\u2013', '-').replace('\u2014', '-').trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	public static String quest(String title)
	{
		String exact = QUESTS.get(normalize(title));
		if (exact != null)
		{
			return exact;
		}
		String name = normalize(title).replaceAll("^(?:start miniquest:|start|complete|finish)\\s+", "")
			.replace("(miniquest)", "").trim();
		String identity = QUESTS.get(name);
		return identity == null ? QUESTS.get(name.replaceAll("\\.$", "")) : identity;
	}

	public static String skill(String name)
	{
		String normalized = normalize(name);
		if (normalized.equals("runecrafting"))
		{
			normalized = "runecraft";
		}
		if (normalized.equals("defense"))
		{
			normalized = "defence";
		}
		for (Skill skill : Skill.values())
		{
			if (normalize(skill.getName()).equals(normalized))
			{
				return skill.name();
			}
		}
		return null;
	}
}

package com.questcape.progress;

import java.util.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.client.config.*;

@Singleton
public class LiveProgressReader
{
	private final Client client;
	private final ConfigManager config;

	@Inject
	public LiveProgressReader(Client client, ConfigManager config)
	{
		this.client = client;
		this.config = config;
	}

	/** Only call on ClientThread after the login's first game tick. */
	public AccountProgress read()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null
			|| config.getRSProfileKey() == null)
		{
			return null;
		}
		String name = client.getLocalPlayer().getName();
		if (name == null || name.isBlank() || client.getAccountHash() == -1L)
		{
			return null;
		}
		RuneScapeProfileType mode = RuneScapeProfileType.getCurrent(client);
		boolean established = config.getRSProfiles().stream().anyMatch(p -> p.getKey().equals(config.getRSProfileKey())
			&& p.getAccountHash() == client.getAccountHash() && p.getType() == mode);
		if (!established)
		{
			return null;
		}
		Map<String, AccountProgress.QuestStatus> quests = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			quests.put(quest.name(), state == QuestState.FINISHED ? AccountProgress.QuestStatus.COMPLETE
				: state == QuestState.IN_PROGRESS ? AccountProgress.QuestStatus.IN_PROGRESS
					: AccountProgress.QuestStatus.INCOMPLETE);
		}
		Map<String, Integer> levels = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			int level = client.getRealSkillLevel(skill);
			if (level > 0)
			{
				levels.put(skill.name(), level);
			}
		}
		ActivityProgress.readMiniquests(client, quests);
		long now = System.currentTimeMillis();
		return new AccountProgress("live:" + config.getRSProfileKey() + ":" + mode.name(), name, mode.name(),
			"Live RuneLite",
			now, now, quests, levels, ActivityProgress.readActivities(client), Collections.emptySet());
	}
}

package com.questcape.progress;

import com.questcape.guide.GuideRow;
import com.questcape.persistence.JsonStore;
import java.io.*;
import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;

/** Disk operations run on the serial worker; client/EDT reads and logout never wait for disk. */
@Singleton
@Slf4j
public class ProgressService
{
	private final JsonStore store;
	private final Map<String, AccountProgress> records = new java.util.concurrent.ConcurrentHashMap<>();
	private volatile AccountProgress live;
	private long session;
	private final Set<String> unreadable = new HashSet<>();
	private volatile String persistenceStatus = "";
	private long nextSaveAt;

	@Inject
	public ProgressService(JsonStore store)
	{
		this.store = store;
	}

	private void load(String scope, boolean retry) throws IOException
	{
		if (records.containsKey(scope) && (!unreadable.contains(scope) || !retry))
		{
			return;
		}
		AccountProgress saved = store.read("progress", scope, AccountProgress.class);
		if (saved != null)
		{
			if (!scope.equals(saved.getScope()) || saved.getQuests() == null || saved.getLevels() == null
				|| saved.getManual() == null || saved.getActivities() == null || saved.getUsername() == null
				|| saved.getMode() == null)
			{
				throw new IOException("Invalid account cache; original retained");
			}
			AccountProgress pending = records.get(scope);
			if (pending != null && unreadable.contains(scope))
			{
				Set<String> checks = new HashSet<>(saved.getManual());
				checks.addAll(pending.getManual());
				saved = saved.withManual(checks);
			}
			records.put(scope, saved);
		}
		unreadable.remove(scope);
	}

	public void acceptLive(AccountProgress observation) throws IOException
	{
		acceptLive(observation, token(), false);
	}

	/** A session token also prevents a disk operation finishing after logout from republishing a character. */
	public boolean acceptLive(AccountProgress observation, long expectedSession, boolean force) throws IOException
	{
		if (observation == null || expectedSession != token())
		{
			return false;
		}
		try
		{
			load(observation.getScope(), force);
		}
		catch (IOException e)
		{
			unreadable.add(observation.getScope());
			log.debug("QuestCape account cache could not be read ({})", e.getClass().getSimpleName());
		}
		AccountProgress current = live;
		boolean unchanged = current != null && current.getScope().equals(observation.getScope())
			&& current.getUsername().equals(observation.getUsername())
			&& current.getQuests().equals(observation.getQuests())
			&& current.getLevels().equals(observation.getLevels())
			&& current.getActivities().equals(observation.getActivities());
		if (!force && unchanged && persistenceStatus.isEmpty()
			&& observation.getRetrievedAt() - current.getRetrievedAt() < 60_000)
		{
			return expectedSession == token();
		}
		AccountProgress previous = records.get(observation.getScope());
		AccountProgress next = observation.withManual(previous == null ? Collections.emptySet() : previous.getManual());
		if (expectedSession != token())
		{
			return false;
		}
		records.put(next.getScope(), next);
		synchronized (this)
		{
			if (expectedSession != session)
			{
				return false;
			}
			live = next;
		}
		if (current == null || !current.getScope().equals(next.getScope()))
		{
			nextSaveAt = 0;
		}
		save(next, expectedSession, force);
		return expectedSession == token();
	}

	/** Worker-only persistence; publication never needs to acquire the store's disk lock. */
	private void save(AccountProgress record, long expectedSession, boolean force)
	{
		long now = System.currentTimeMillis();
		String status = "Live progress · unsaved; cache unavailable. Sync to retry.";
		if (!unreadable.contains(record.getScope()) && (force || now >= nextSaveAt))
		{
			try
			{
				store.write("progress", record.getScope(), record);
				status = "";
				nextSaveAt = 0;
			}
			catch (IOException e)
			{
				nextSaveAt = now + 60_000;
				log.debug("QuestCape progress cache write failed ({})", e.getClass().getSimpleName());
			}
		}
		synchronized (this)
		{
			if (session == expectedSession)
			{
				persistenceStatus = status;
			}
		}
	}

	public String persistenceStatus()
	{
		return persistenceStatus;
	}

	public synchronized void logout()
	{
		live = null;
		persistenceStatus = "";
		session++;
	}

	public synchronized long token()
	{
		return session;
	}

	public AccountProgress current()
	{
		return live;
	}

	public void toggleManual(String expectedScope, GuideRow row, boolean checked) throws IOException
	{
		long expectedSession = token();
		AccountProgress record = live;
		if (record == null || !record.getScope().equals(expectedScope) || !row.isManual())
		{
			return;
		}
		Set<String> checks = new HashSet<>(record.getManual());
		if (checked)
		{
			checks.add(row.getKey());
		}
		else
		{
			checks.remove(row.getKey());
		}
		AccountProgress changed = record.withManual(checks);
		records.put(changed.getScope(), changed);
		synchronized (this)
		{
			if (expectedSession == session && live == record)
			{
				live = changed;
			}
		}
		save(changed, expectedSession, true);
	}
}

package com.questcape.ui;

import com.questcape.progress.Completion;
import java.awt.*;
import javax.swing.Icon;

/** Small local vector controls; no image downloads or additional resources. */
final class GuideControlIcons
{
	private GuideControlIcons()
	{
	}

	static final class FilterIcon implements Icon
	{
		private final boolean state, active;

		FilterIcon(boolean state, boolean active)
		{
			this.state = state;
			this.active = active;
		}
		public int getIconWidth() { return 28; }
		public int getIconHeight() { return 18; }
		public void paintIcon(Component c, Graphics original, int x, int y)
		{
			Graphics2D g = graphics(c, original, x, y, active ? GuidePanel.BLUE : GuidePanel.MUTED);
			try
			{
				g.drawPolyline(new int[] {1, 15, 10, 10, 6, 6, 1}, new int[] {3, 3, 9, 15, 13, 9, 3}, 7);
				if (state)
				{
					g.drawOval(18, 5, 8, 8);
					g.drawPolyline(new int[] {20, 22, 25}, new int[] {9, 11, 7}, 3);
				}
				else
				{
					for (int line = 5; line <= 13; line += 4)
					{
						g.drawLine(19, line, 26, line);
					}
				}
			}
			finally { g.dispose(); }
		}
	}

	static final class StateIcon implements Icon
	{
		private final Completion.State state;

		StateIcon(Completion.State state) { this.state = state; }
		public int getIconWidth() { return 16; }
		public int getIconHeight() { return 16; }
		public void paintIcon(Component c, Graphics original, int x, int y)
		{
			Graphics2D g = graphics(c, original, x, y, GuidePanel.stateColor(state));
			try
			{
				g.setFont(c.getFont());
				FontMetrics metrics = g.getFontMetrics();
				String symbol = new Completion(state, false).label().substring(0, 1);
				g.drawString(symbol, (16 - metrics.stringWidth(symbol)) / 2,
					(16 - metrics.getHeight()) / 2 + metrics.getAscent());
			}
			finally { g.dispose(); }
		}
	}

	static final class ChevronIcon implements Icon
	{
		public int getIconWidth() { return 9; }
		public int getIconHeight() { return 12; }
		public void paintIcon(Component c, Graphics original, int x, int y)
		{
			Graphics2D g = graphics(c, original, x, y, GuidePanel.MUTED);
			try { g.drawPolyline(new int[] {1, 4, 7}, new int[] {4, 7, 4}, 3); }
			finally { g.dispose(); }
		}
	}

	static final class ContinueIcon implements Icon
	{
		public int getIconWidth() { return 10; }
		public int getIconHeight() { return 12; }
		public void paintIcon(Component c, Graphics original, int x, int y)
		{
			Graphics2D g = graphics(c, original, x, y, GuidePanel.BLUE);
			try { g.fillPolygon(new int[] {1, 1, 9}, new int[] {1, 11, 6}, 3); }
			finally { g.dispose(); }
		}
	}

	private static Graphics2D graphics(Component c, Graphics original, int x, int y, Color color)
	{
		Graphics2D g = (Graphics2D)original.create();
		g.translate(x, y);
		g.setColor(c.isEnabled() ? color : GuidePanel.BORDER);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		return g;
	}
}

