package com.questcape.ui;

import java.util.*;
import java.util.regex.*;
import java.util.stream.Collectors;
import net.runelite.api.Skill;

/** Parses stored guide text only; projected levels never become character facts. */
final class ProjectedLevels
{
	private static final Pattern LEVEL = Pattern.compile("(?i)(\\d{1,3})\\s+("
		+ Arrays.stream(Skill.values()).map(s -> s.getName()).sorted(Comparator.comparingInt(String::length).reversed())
			.map(Pattern::quote).collect(Collectors.joining("|")) + ")\\b");

	static final class Entry
	{
		final int level;
		final Skill skill;

		Entry(int level, Skill skill)
		{
			this.level = level;
			this.skill = skill;
		}
	}

	private ProjectedLevels()
	{
	}

	static List<Entry> parse(String text)
	{
		Matcher matcher = LEVEL.matcher(text);
		List<Entry> entries = new ArrayList<>();
		while (matcher.find())
		{
			int level = Integer.parseInt(matcher.group(1));
			if (level < 1 || level > 126)
			{
				return Collections.emptyList();
			}
			for (Skill skill : Skill.values())
			{
				if (skill.getName().equalsIgnoreCase(matcher.group(2)))
				{
					entries.add(new Entry(level, skill));
					break;
				}
			}
		}
		// Preserve unfamiliar/annotated source text verbatim instead of silently dropping it.
		return LEVEL.matcher(text).replaceAll("").replaceAll("[\\s,;]+", "").isEmpty()
			? entries : Collections.emptyList();
	}
}

package com.questcape.ui;

import com.questcape.progress.Identities;
import java.awt.*;
import java.util.*;
import java.util.regex.*;
import java.util.stream.Collectors;
import javax.swing.*;
import javax.swing.text.*;
import net.runelite.api.Skill;

/** Inert styled text: skill icons come only from RuneLite, never the guide's image URLs. */
final class SkillText extends JTextPane
{
	private static final Icon PENDING_ICON = new Icon()
	{
		public int getIconWidth() { return 16; }
		public int getIconHeight() { return 16; }
		public void paintIcon(Component c, Graphics g, int x, int y) { }
	};
	private static final Pattern MENTION = Pattern.compile("(?i)(?<![\\p{L}\\p{N}_])(" +
		Arrays.stream(Skill.values()).map(Skill::getName).map(Pattern::quote).collect(Collectors.joining("|"))
		+ "|Runecrafting|Defense)(?![\\p{L}\\p{N}_])");
	private final Map<Integer, Skill> icons = new LinkedHashMap<>();

	SkillText(String source, Font font, Color color, Map<Skill, Icon> images)
	{
		setFont(font);
		setForeground(color);
		setOpaque(false);
		setEditable(false);
		setAlignmentX(LEFT_ALIGNMENT);
		setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		((DefaultCaret)getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		getAccessibleContext().setAccessibleName(source);
		Matcher matcher = MENTION.matcher(source);
		StringBuilder text = new StringBuilder();
		int end = 0;
		while (matcher.find())
		{
			String identity = Identities.skill(matcher.group());
			text.append(source, end, matcher.start());
			if (identity != null)
			{
				icons.put(text.length(), Skill.valueOf(identity));
				text.append('\ufffc').append(' ');
			}
			text.append(matcher.group());
			end = matcher.end();
		}
		text.append(source.substring(end));
		setText(text.toString());
		updateIcons(images);
	}

	void updateIcons(Map<Skill, Icon> images)
	{
		icons.forEach((offset, skill) ->
		{
			SimpleAttributeSet attributes = new SimpleAttributeSet();
			StyleConstants.setIcon(attributes, images.getOrDefault(skill, PENDING_ICON));
			getStyledDocument().setCharacterAttributes(offset, 1, attributes, true);
		});
	}

	@Override
	public Dimension getPreferredSize()
	{
		int width = getWidth() > 0 ? getWidth() : 180;
		Insets insets = getInsets();
		View root = getUI().getRootView(this);
		root.setSize(Math.max(1, width - insets.left - insets.right), Integer.MAX_VALUE);
		return new Dimension(width, (int)Math.ceil(root.getPreferredSpan(View.Y_AXIS)) + insets.top + insets.bottom);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(10, getPreferredSize().height);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

package com.questcape.ui;

import com.questcape.guide.GuideRow;
import java.awt.*;
import java.awt.geom.Path2D;
import javax.swing.Icon;

/** Small vector fallbacks until RuneLite's standard quest, diary and skills sprites are available. */
final class StepIcons implements Icon
{
	private final GuideRow.Kind kind;
	private final Icon questIcon;

	StepIcons(GuideRow.Kind kind)
	{
		this(kind, null);
	}

	StepIcons(GuideRow.Kind kind, Icon questIcon)
	{
		this.kind = kind;
		this.questIcon = questIcon;
	}

	@Override
	public int getIconWidth()
	{
		return 16;
	}

	@Override
	public int getIconHeight()
	{
		return 16;
	}

	@Override
	public void paintIcon(Component component, Graphics graphics, int x, int y)
	{
		Graphics2D g = (Graphics2D)graphics.create();
		try
		{
			g.translate(x, y);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(GuidePanel.kindColor(kind));
			switch (kind)
			{
			case QUEST:
			case MINIQUEST:
			case DIARY:
				if (questIcon != null)
				{
					questIcon.paintIcon(component, g, 0, 0);
				}
				else
				{
					g.setColor(kind == GuideRow.Kind.DIARY ? GuidePanel.GREEN : GuidePanel.BLUE);
					Path2D star = new Path2D.Double();
					star.moveTo(8, 1);
					star.lineTo(10, 6);
					star.lineTo(15, 8);
					star.lineTo(10, 10);
					star.lineTo(8, 15);
					star.lineTo(6, 10);
					star.lineTo(1, 8);
					star.lineTo(6, 6);
					star.closePath();
					g.fill(star);
					g.setColor(GuidePanel.TEXT);
					g.drawLine(8, 4, 8, 11);
				}
				if (kind == GuideRow.Kind.MINIQUEST)
				{
					g.setColor(GuidePanel.CARD);
					g.fillOval(9, 9, 7, 7);
					g.setColor(GuidePanel.GOLD);
					g.fillOval(10, 10, 5, 5);
				}
				break;
			case TRAINING:
				g.fillRect(1, 10, 3, 5);
				g.fillRect(6, 6, 3, 9);
				g.fillRect(11, 1, 3, 14);
				break;
			case UNLOCK:
				g.drawArc(4, 1, 8, 10, 0, 180);
				g.fillRoundRect(2, 6, 12, 9, 3, 3);
				g.setColor(GuidePanel.CARD);
				g.drawLine(8, 9, 8, 12);
				break;
			case ACTIVITY:
				g.drawRoundRect(2, 2, 12, 13, 2, 2);
				g.fillRoundRect(5, 0, 6, 4, 2, 2);
				g.drawLine(5, 9, 7, 11);
				g.drawLine(7, 11, 11, 6);
				break;
			default:
				g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 16));
				g.drawString("?", 4, 14);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.questcape.ui;

import java.util.Locale;

/** Bounded title matching, with route order used to break equal scores. */
final class StepSearch
{
	private StepSearch()
	{
	}

	static String normalize(String value)
	{
		return value.toLowerCase(Locale.ROOT).replaceAll("[^\\p{L}\\p{N}]+", " ").trim();
	}

	static int score(String title, String query)
	{
		String name = normalize(title), needle = normalize(query);
		if (needle.isEmpty() || needle.length() > 160)
		{
			return Integer.MAX_VALUE;
		}
		if (name.equals(needle))
		{
			return 0;
		}
		if (name.startsWith(needle))
		{
			return 10;
		}
		if (name.contains(needle))
		{
			return 20;
		}
		boolean tokens = true;
		for (String word : needle.split(" "))
		{
			tokens &= name.contains(word);
		}
		if (tokens)
		{
			return 30;
		}
		if (needle.length() < 3)
		{
			return Integer.MAX_VALUE;
		}
		int distance = distance(name, needle);
		for (String word : name.split(" "))
		{
			distance = Math.min(distance, distance(word, needle));
		}
		return distance <= Math.max(1, needle.length() / 4) ? 40 + distance : Integer.MAX_VALUE;
	}

	private static int distance(String a, String b)
	{
		if (Math.abs(a.length() - b.length()) > Math.max(1, b.length() / 4))
		{
			return Integer.MAX_VALUE;
		}
		int[] previous = new int[b.length() + 1];
		for (int j = 0; j <= b.length(); j++)
		{
			previous[j] = j;
		}
		for (int i = 1; i <= a.length(); i++)
		{
			int[] current = new int[b.length() + 1];
			current[0] = i;
			for (int j = 1; j <= b.length(); j++)
			{
				current[j] = Math.min(Math.min(current[j - 1] + 1, previous[j] + 1),
					previous[j - 1] + (a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1));
			}
			previous = current;
		}
		return previous[b.length()];
	}
}

